<?php
require __DIR__.'/../config/config.php'; require_admin();
$msg='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['name']);$email=trim($_POST['email']);$pass=$_POST['password'];if(strlen($pass)<10){$error='Password must be at least 10 characters.';}else{try{$s=db()->prepare("INSERT INTO admins(name,email,password_hash) VALUES(?,?,?)");$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);$msg='Admin created.';}catch(Throwable $e){$error='Could not create admin. Email may already exist.';}}}
$rows=db()->query("SELECT id,name,email,created_at FROM admins ORDER BY id DESC")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admins</title><link rel="stylesheet" href="admin.css"></head><body><div class="layout"><aside class="side"><h2>GBU ADMIN</h2><a href="index.php">Dashboard</a><a href="notices.php">Notices</a><a href="courses.php">Courses</a><a href="events.php">Events</a><a class="active" href="admins.php">Admins</a><a href="logout.php">Logout</a></aside><main class="main"><h1>Admin Users</h1><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><div class="panel"><h2>Create Admin</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="formgrid"><div><label>Name</label><input name="name" required></div><div><label>Email</label><input type="email" name="email" required></div></div><label>Password</label><input type="password" name="password" minlength="10" required><button class="button gold">Create Admin</button></form></div><div class="panel"><table class="table"><tr><th>Name</th><th>Email</th><th>Created</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></table></div></main></div></body></html>